 {tab==='tasks'&&<><section className="page-title"><div><div className="eyebrow">{t('ONE THING AT A TIME')}</div><h1>{t('A little less on your mind')}</h1><p>{t('Turn intentions into small, doable steps.')}</p></div><button className="round-add" aria-label={t('Add a task')} onClick={()=>openTask()}><Plus size={23}/></button></section><section className="task-summary"><div><b>{realStats.total?realStats.percentage+'%':'—'}</b><span>{t('of today’s tasks complete')}</span></div><span>{realStats.completed} / {realStats.total}</span><div className="progress-track"><i style={{width:`${realStats.total?realStats.percentage+'%':'—'}`}}/></div></section><div className="search-field"><Search size={18}/><input aria-label={t('Search tasks')} placeholder={t('Search tasks')} value={search} onChange={e=>setSearch(e.target.value)}/><SlidersHorizontal size={17}/></div><div className="task-filters">{['all','today','open','overdue','done'].map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{t(f==='all'?'All tasks':f==='today'?'Today':f==='open'?'To do':f==='overdue'?'Overdue':'Completed')}</button>)}<select aria-label={t('Category')} value={category} onChange={e=>setCategory(e.target.value)}><option value="all">{t('All categories')}</option>{[...new Set(state.tasks.map(t=>t.category))].map(c=><option key={c}>{c}</option>)}</select></div><label className="grouping-control">{t('Group tasks')}<select value={taskGrouping} onChange={e=>setTaskGrouping(e.target.value)}><option value="date">{t('By date')}</option><option value="category">{t('By category')}</option></select></label><section className="section task-list">{taskGroups.length?taskGroups.map(([heading,items])=><div className="task-group" key={heading}><h3>{taskGrouping==='date'?dateLabel(heading,{weekday:'short',day:'numeric',month:'short'}):heading}<span>{items.length}</span></h3>{items.map(task=><div style={{'--accent':categoryColor(task.category,task.color)} as CSSProperties} className={'task-row '+(task.completed?'task-done':'')} key={task.id}><button className="task-check" disabled={busy} aria-label={t(task.completed?'Mark incomplete':'Complete task')} onClick={()=>dispatch({type:'task',task:{...task,completed:!task.completed}})}>{task.completed&&<Check size={15}/>}</button><button className="task-body" onClick={()=>openTask(task)}><b>{task.title}</b>{task.description&&<p className="task-description">{task.description}</p>}{task.subtasks?.length? <small className="subtask-count">{task.subtasks.filter(x=>x.completed).length}/{task.subtasks.length} {t('subtasks')}</small>:null}<span><i className={'priority-dot '+task.priority}/>{t(task.priority)}<span className="meta-divider">·</span>{task.category}<span className={'due-date '+(!task.completed&&task.date<today()?'overdue':'')}>{dateLabel(task.date,{day:'numeric',month:'short'})}{task.recurrence!=='none'&&' ↻'}</span></span></button><button className="icon-button task-edit" aria-label={t('Edit task')} onClick={()=>openTask(task)}><Pencil size={16}/></button></div>)}</div>):<div className="empty"><span className="empty-icon"><ListTodo size={26}/></span><h3>{t('A fresh page for your intentions')}</h3><p>{t('Add one small task. That is enough to begin.')}</p><Button onClick={()=>openTask()}><Plus size={16}/>{t('Add a task')}</Button></div>}</section><div className="gentle-note"><Leaf size={16}/>{t('Progress has no perfect pace. Yours is enough.')}</div></>}
 {tab==='progress'&&<><section className="page-title"><div><div className="eyebrow">{t('YOUR JOURNEY, HONESTLY')}</div><h1>{t('Small steps add up')}</h1><p>{t('Every number here comes from your own activity.')}</p></div><span className="title-icon"><BarChart3 size={24}/></span></section><WeeklyReport state={state} t={t}/><section className="progress-hero"><div className="progress-hero-main"><ProgressRing percent={realStats.percentage} size={182}><strong>{realStats.percentage}<small>%</small></strong><span>{t('today complete')}</span></ProgressRing><div><span className="overline">{t('STEADY IS STRONG')}</span><h2>{realStats.activeDays}<small> / 7</small></h2><p>{t('active days this week')}</p><div className="week-consistency">{realStats.history.slice(-7).map(h=><span key={h.date} className={h.completed||h.habitChecks||h.xp?'filled':''}>{h.completed||h.habitChecks||h.xp?<Check size={12}/>:<i/>}</span>)}</div></div></div><div className="hero-foot"><span><Leaf size={15}/>{t('Level')} {realStats.level}</span><b>{realStats.xp} XP <span>{t('earned, never erased')}</span></b></div><div className="level-progress"><span>{t('Next level')} · {realStats.xp%300}/300 XP</span><div className="progress-track"><i style={{width:`${realStats.xp%300/3}%`}}/></div></div></section><div className="stat-grid"><div><span className="stat-icon"><CheckCheck size={19}/></span><b>{realStats.totalCompleted}</b><span>{t('Completed tasks')}</span></div><div><span className="stat-icon gold"><Trophy size={19}/></span><b>{realStats.completedMarathons}</b><span>{t('Completed marathons')}</span></div><div><span className="stat-icon"><Flame size={19}/></span><b>{realStats.bestDay}</b><span>{t('Best daily task count')}</span></div><div><span className="stat-icon gold"><Zap size={19}/></span><b>{realStats.xp}</b><span>{t('Total XP')}</span></div></div><section className="section trend-section"><div className="section-header"><div><h2>{t('Your rhythm')}</h2><p>{t('Completed tasks · last 30 days')}</p></div><span className="small-badge">{realStats.monthly.completed} / {realStats.monthly.total}</span></div><div className="trend-chart" role="img" aria-label={t('Task completion over the last 30 days')}>{realStats.history.map(h=><div key={h.date} title={`${h.date}: ${h.completed}/${h.total}`}><i style={{height:`${h.completed?Math.max(5,h.completed/Math.max(1,...realStats.history.map(h=>h.completed))*100):2}%`}}/><span>{Number(h.date.slice(-2))%5===0?h.date.slice(-2):''}</span></div>)}</div><div className="chart-legend"><span><i/>{t('Your confirmed completions')}</span><b>{realStats.weekly.completed} {t('this week')}</b></div></section><div className="dashboard-lower"><section className="section"><div className="section-header"><h2>{t('The days you showed up')}</h2><CalendarDays size={17}/></div><div className="heatmap">{realStats.history.map(h=><div key={h.date} title={`${h.date}: ${h.completed} + ${h.habitChecks}`} className={'heat-cell intensity-'+Math.min(3,h.completed+h.habitChecks)}><span>{Number(h.date.slice(-2))}</span></div>)}</div><div className="heatmap-legend"><span>{t('Less')}</span>{[0,1,2,3].map(n=><i key={n} className={'intensity-'+n}/>)}<span>{t('More')}</span></div></section><section className="section"><div className="section-header"><h2>{t('Quiet achievements')}</h2><Trophy size={18}/></div>{[{earned:realStats.totalCompleted>0||!!state.earnedAchievements['first-task'],label:'First step',description:'Complete your first task',icon:CheckCheck},{earned:realStats.xp>=100||!!state.earnedAchievements['hundred-xp'],label:'Finding your rhythm',description:'Earn your first 100 XP',icon:Leaf},{earned:realStats.completedMarathons>0||!!state.earnedAchievements.marathon,label:'A chapter complete',description:'Finish a 21-day marathon',icon:Target}].map(a=><div className={'achievement '+(a.earned?'earned':'')} key={a.label}><span><a.icon size={21}/></span><div><b>{t(a.label)}</b><small>{t(a.description)}</small></div>{a.earned?<CheckCircle2 size={17}/>:<Lock size={15}/>}</div>)}</section></div><section className="section"><div className="section-header"><h2>{t('Habit history')}</h2><button className="text-link" onClick={()=>navigate('planner')}>{t('View habits')}<ArrowUpRight size={15}/></button></div>{state.habits.length?state.habits.map(h=><div className="habit-history" key={h.id}><div><b>{publicHabitTitle(state,h,t)}</b><span>{Object.values(h.checks).reduce((a,b)=>a+b,0)} {t('check-ins')}</span></div><div>{realStats.history.map(d=><i key={d.date} title={`${d.date}: ${h.checks[d.date]||0}`} className={h.checks[d.date]?'filled':''}/>)}</div></div>):<p className="gentle-copy">{t('Your habit history will grow with each check-in.')}</p>}</section><section className="section"><div className="section-header"><h2>{t('Your XP history')}</h2><Zap size={17}/></div>{realStats.history.filter(h=>h.xp).length?realStats.history.filter(h=>h.xp).reverse().slice(0,7).map(h=><div className="history-row" key={h.date}><span>{dateLabel(h.date,{month:'short',day:'numeric'})}</span><b>+{h.xp} XP</b></div>):<p className="gentle-copy">{t('Your first small win will appear here.')}</p>}</section></>}
 {tab==='marathons'&&<>{selectedAttempt?(()=>{const e=selectedAttempt,c=planFor(e.challenge_id),m=marathonMetrics(e),day=reviewDay||m.currentDay;return <><button className="back-link" onClick={()=>{setDetail(null);setReviewDay(null)}}><ArrowLeft size={17}/>{t('All marathons')}</button><section className="page-title marathon-title"><div><div className="eyebrow">{t(c.category)} · 21 {t('days')}</div><h1>{t(c.title)}</h1><p>{t(c.description)}</p></div></section><section style={{'--accent':categoryColor(c.category,'color'in c?c.color as string:undefined)} as CSSProperties} className="signature-marathon"><div className="signature-top"><span><span className={'status-dot '+(e.pausedOn?'paused':'')}/>{t(e.days.length===21?'Complete':e.pausedOn?'Paused':'YOUR 21-DAY PRACTICE')}</span><span className="marathon-symbol">✦</span></div><ProgressRing percent={m.percentage} size={248} gold><span className="ring-day-label">{t('DAY')}</span><strong className="marathon-day-number">{m.currentDay.toString().padStart(2,'0')}</strong><span className="ring-of">{t('OF')} 21</span></ProgressRing><div className="marathon-ring-stats"><div><b>{m.completedDays}</b><span>{t('Completed')}</span></div><div><b>{m.remainingDays}</b><span>{t('Remaining')}</span></div><div><b>{m.percentage}<small>%</small></b><span>{t('Progress')}</span></div></div><div className="marathon-calendar-stats"><span>{m.elapsedDays} {t('elapsed days')}</span><span>{m.missedDays} {t('missed activity days')}</span></div></section>
 {e.days.length===21?<section className="section completion-section"><Trophy size={34}/><h2>{t('You showed up for yourself.')}</h2><p>{t('Keep what helped. Your next chapter can be a gentle habit.')}</p><Button disabled={e.maintenance||busy} onClick={async()=>{if(await dispatch({type:'maintenance',id:e.id})){notify('A maintenance habit was added.');setTab('planner');setDetail(null)}}}><Leaf size={17}/>{t(e.maintenance?'Maintenance habit added':'Continue as a habit')}</Button><Button variant="outline" onClick={()=>download('nafs-certificate.json',JSON.stringify({title:t('21-day completion certificate'),marathon:t(c.title),activities:21,completed:e.completedDates,issued:today(),developer:'Werllap'},null,2))}><Download size={16}/>{t('Download certificate')}</Button><button className="text-link" onClick={()=>startMarathon(c)}>{t('Replay marathon')}<ArrowRight size={15}/></button></section>:<section className="section activity-card"><div className="section-header"><span className="small-badge">{t('Day')} {day}</span><span className="activity-stage">{t(day<=7?'Beginning':day<=14?'Consistency':'Reinforcement')}</span></div><label>{t('Practice intensity')}<select value={e.intensity||'balanced'} onChange={event=>dispatch({type:'intensity',id:e.id,value:event.target.value as 'gentle'|'balanced'|'intense'})}>{['gentle','balanced','intense'].map(v=><option key={v} value={v}>{t('intensity.'+v)}</option>)}</select></label><h2>{e.programSnapshot?activityForAttempt(e.programSnapshot,day,e.intensity).instructions:t(c.days[day-1])}</h2><div className="activity-details"><p>{t((e.programSnapshot?activityForAttempt(e.programSnapshot,day,e.intensity):activityDetails(c,day,e.intensity,locale)).reason)}</p><dl><div><dt>{t('Suggested duration')}</dt><dd>{(e.programSnapshot?activityForAttempt(e.programSnapshot,day,e.intensity):activityDetails(c,day,e.intensity,locale)).minutes} {t('min')} · {t('adjust to your needs')}</dd></div><div><dt>{t('Completion criteria')}</dt><dd>{t((e.programSnapshot?activityForAttempt(e.programSnapshot,day,e.intensity):activityDetails(c,day,e.intensity,locale)).criteria)}</dd></div></dl><details><summary>{t('Optional reflection')}</summary><p>{t((e.programSnapshot?activityForAttempt(e.programSnapshot,day,e.intensity):activityDetails(c,day,e.intensity,locale)).reflection)}</p></details></div><p>{t(e.pausedOn?'Your practice is paused. Resume when you are ready.':e.days.includes(day)?'A small promise you kept. This activity is complete.':'One deliberate action. No need to rush.')}</p><Button disabled={busy||!!e.archived||!!e.pausedOn||e.days.includes(day)||day>m.unlockedDay} onClick={()=>dispatch({type:'progress',id:e.id,day})}><Check size={18}/>{t(e.days.includes(day)?'Activity completed':day>m.unlockedDay?'Available on a future day':'I completed this activity')}</Button>{!e.days.includes(day)&&day<=m.unlockedDay&&!e.pausedOn&&<ContextMotivation state={state} dispatch={dispatch} t={t} busy={busy} context="before"/>}{isSensitive(e.challenge_id)&&!e.archived&&<Button variant="outline" disabled={busy} onClick={()=>{if(confirm(t('Setback confirmation')))dispatch({type:'setback',id:e.id,newId:uid()}).then(ok=>{if(ok)setDetail(null)})}}>{t('Start after a setback')}</Button>}<button className="text-link" disabled={busy} onClick={()=>{if(confirm(t('Start a new attempt? Your previous progress remains in history.')))dispatch({type:'restart',id:e.id,newId:uid(),startDate:today()}).then(ok=>{if(ok)setDetail(null)})}}>{t('Restart with a new attempt')}</button><button className="text-link pause-link" disabled={busy} onClick={()=>dispatch({type:e.pausedOn?'resume':'pause',id:e.id})}>{e.pausedOn?<Play size={15}/>:<Pause size={15}/>} {t(e.pausedOn?'Resume marathon':'Pause marathon')}</button></section>}
 <section className="section"><div className="section-header"><h2>{t('Your 21-day chapter')}</h2><span className="muted">{t('Tap a day to review')}</span></div><div className="marathon-days">{Array.from({length:21},(_,i)=>i+1).map(d=><button className={(e.days.includes(d)?'completed ':'')+(day===d?'selected ':'')+(d>m.unlockedDay?'future':'')} key={d} onClick={()=>setReviewDay(d)} aria-label={`${t('Day')} ${d}`}><span>{d}</span>{e.days.includes(d)?<Check size={13}/>:<i/>}</button>)}</div><p className="method-note">{t('The ring counts completed activities, never days merely elapsed. A missed day does not erase your progress.')}</p></section></>})():<><section className="page-title"><div><div className="eyebrow">{t('21 DAYS. YOUR OWN PACE.')}</div><h1>{t('Begin a meaningful chapter')}</h1><p>{t('A practice, not a promise of a permanent habit.')}</p></div><button className="round-add" aria-label={t('Create a marathon')} onClick={()=>{setEditingCustom(null);setDialog('custom')}}><Plus size={23}/></button></section>{active.length>0&&<section className="active-marathons"><div className="section-header"><h2>{t('Your active marathons')}</h2><span className="small-badge">{active.length}</span></div><div className="active-marathon-grid">{active.filter(e=>marathonFilter!=='paused'||e.pausedOn).filter(e=>marathonFilter!=='active'||!e.pausedOn).map(e=>{const c=planFor(e.challenge_id),m=marathonMetrics(e);return <button className="active-marathon" key={e.id} onClick={()=>{setDetail(e.id);setReviewDay(null)}}><ProgressRing percent={m.percentage} size={104}><span className="small-ring-label">{t('DAY')}</span><strong>{m.currentDay}</strong><span>{t('OF')} 21</span></ProgressRing><div><span className="overline">{t(e.pausedOn?'Paused':'IN PROGRESS')}</span><h3>{concealedTitle(c,state.preferences,t)}</h3><p>{m.completedDays} / 21 {t('completed')} · {m.percentage}%</p></div><ArrowUpRight size={19}/></button>})}</div></section>}<div className="search-field"><Search size={18}/><input aria-label={t('Search marathons')} placeholder={t('Find your next intention')} value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="task-filters">{['all','active','paused','completed','custom'].map(f=><button key={f} className={marathonFilter===f?'active':''} onClick={()=>setMarathonFilter(f)}>{t(f==='all'?'All marathons':f==='active'?'Active':f==='paused'?'Paused':f==='completed'?'Completed':'Custom')}</button>)}<select aria-label={t('Category')} value={category} onChange={e=>setCategory(e.target.value)}><option value="all">{t('All categories')}</option>{[...new Set(catalog.map(c=>c.category))].map(c=><option key={c} value={c}>{t(c)}</option>)}</select></div><div className="marathon-catalog">{catalog.filter(c=>(!('archived'in c&&c.archived)||marathonFilter==='custom')&&(category==='all'||c.category===category)&&t(c.title).toLowerCase().includes(search.toLowerCase())&&(marathonFilter==='all'&&!active.some(e=>e.challenge_id===c.id)||marathonFilter==='custom'&&state.customChallenges.some(x=>x.id===c.id))).map((c,i)=>{const Icon=icons[c.icon as keyof typeof icons]||Target,e=active.find(e=>e.challenge_id===c.id);return <article style={{'--accent':categoryColor(c.category,'color'in c?c.color as string:undefined)} as CSSProperties} className={'marathon-card tone-'+i%4} key={c.id}><div className="marathon-card-top"><span className="catalog-symbol"><Icon size={25} strokeWidth={1.5}/></span><span>{t(c.category)}</span><i>✦</i></div><h2>{t(c.title)}</h2><p>{t(c.description)}</p><span className="marathon-difficulty">{t(c.difficulty)}{state.enrollments.some(e=>e.challenge_id===c.id&&e.days.length===21)?' · '+t('Completed'):''}</span>{state.customChallenges.some(x=>x.id===c.id)&&<button className="text-link" onClick={()=>{setEditingCustom(c as CustomChallenge);setDialog('custom')}}><Pencil size={13}/>{t('Edit plan')}</button>}<div className="marathon-card-foot"><span><Clock size={12}/>21 {t('days')}</span><button onClick={()=>startMarathon(c)}>{t(e?.pausedOn?'Resume marathon':e?'Continue':state.enrollments.some(x=>x.challenge_id===c.id&&x.days.length===21)?'Replay marathon':'Begin')}<ArrowUpRight size={18}/></button></div></article>})}</div>{marathonFilter==='completed'&&<section className="section"><h2>{t('Completed chapters')}</h2>{state.enrollments.filter(e=>e.days.length===21).map(e=><button className="completed-chapter" key={e.id} onClick={()=>setDetail(e.id)}><Trophy size={20}/><b>{concealedTitle(planFor(e.challenge_id),state.preferences,t)}</b><span>21 / 21</span><ArrowUpRight size={16}/></button>)}{!state.enrollments.some(e=>e.days.length===21)&&<p>{t('Your completed chapters will live here.')}</p>}</section>}{state.enrollments.some(e=>e.archived)&&<section className="section"><h2>{t('Previous attempts')}</h2>{state.enrollments.filter(e=>e.archived).map(e=><button className="completed-chapter" key={e.id} onClick={()=>setDetail(e.id)}><Clock size={18}/><b>{concealedTitle(planFor(e.challenge_id),state.preferences,t)}</b><span>{e.days.length}/21</span><ArrowUpRight size={16}/></button>)}</section>}<div className="gentle-note"><ShieldCheck size={16}/>{t('Every marathon is free. Every new beginning counts.')}</div></>}</>}
